CREATE VIEW nabz_mali90 AS SELECT TOP(90) DEED_HED.DATE_S, SUM(DEED_DTL.BED) AS mab, dbo.Uday(dbo.DEED_HED.DATE_S) AS dd, dbo.Umonth(dbo.DEED_HED.DATE_S) AS mm FROM DEED_DTL INNER JOIN DEED_HED ON DEED_DTL.N_S = DEED_HED.N_S WHERE (DEED_DTL.HES = N'111-8-1') GROUP BY DEED_HED.DATE_S, dbo.Uday(dbo.DEED_HED.DATE_S), dbo.Umonth(dbo.DEED_HED.DATE_S) ORDER BY DEED_HED.DATE_S DESC
